package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class CreateOrderService implements CreateOrderUseCase {
 private final CustomerRepositoryPort customers; private final CartRepositoryPort carts; private final InventoryRepositoryPort inventories; private final OrderRepositoryPort orders; private final OperationAuditPort audit;
 public CreateOrderService(CustomerRepositoryPort c,CartRepositoryPort ca,InventoryRepositoryPort i,OrderRepositoryPort o,OperationAuditPort a){customers=c;carts=ca;inventories=i;orders=o;audit=a;}
 public Order createOrder(User actor,String cid,String orderId){Customer c=ServiceSupport.required(customers.findById(cid),"Customer",cid);ServiceSupport.sameCustomer(actor,c);Cart cart=ServiceSupport.required(carts.findActiveByCustomer(c),"Cart",cid);if(cart.getItems().isEmpty())throw new DomainRuleException("Cart is empty");Order order=new Order(orderId,c);for(CartItem item:cart.getItems()){Inventory inv=ServiceSupport.required(inventories.findByProduct(item.product()),"Inventory",item.product().getId());if(inv.getAvailable()<item.quantity())throw new DomainRuleException("Insufficient stock for "+item.product().getId());}for(CartItem item:cart.getItems()){Inventory inv=inventories.findByProduct(item.product()).orElseThrow();inv.reserve(item.quantity());inventories.update(inv);order.addItem(item.product(),item.quantity());}order.calculateTotal();order.changeStatus(DomainTypes.OrderStatus.PENDING_PAYMENT);Order saved=orders.save(order);c.addOrder(saved);cart.clear();carts.update(cart);customers.update(c);audit.record(actor,"CREATE_ORDER",saved.getId(),Map.of("total",saved.getTotal()));return saved;}
}
